const $=s=>document.querySelector(s);const icon=n=>`<img class="icon" src="assets/icons/${n}.svg" alt="">`;
let state={page:'car',skin:localStorage.getItem('ble-skin')||'cockpit',paired:true,connected:true,locked:true,frunk:false,trunk:false,confirm:true,scan:'idle',pairStep:0};let timer,toastTimer,modalReturn;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
function navigate(page){clearTimeout(timer);$('#overlay').innerHTML='';state.page=page;render();$('#screen').scrollTop=0}
function header(title,subtitle='',back=false){return `<header class="${back?'sub':''}">${back?`<button class="back" aria-label="返回" onclick="navigate('me')">${icon('arrow-left')}</button>`:''}<div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${!back?`<button class="gear" aria-label="设置" onclick="navigate('settings')">${icon('gear')}</button>`:''}</header>`}
function render(){let page=state.page;$('#nav-car').innerHTML=icon('car-front')+'车辆';$('#nav-me').innerHTML=icon('person')+'我的';$('#nav-car').className=page==='car'?'active':'';$('#nav-me').className=page!=='car'?'active':'';$('#nav-car').setAttribute('aria-current',page==='car'?'page':'false');$('#nav-me').setAttribute('aria-current',page!=='car'?'page':'false');$('#screen').innerHTML=page==='car'?car():page==='me'?me():page==='skin'?skin():page==='add'?add():page==='keys'?keys():settings()}
function status(){return `<button class="status" style="width:calc(100% - 78px)" onclick="connection()"><span><i class="dot ${state.connected?'':'off'}"></i>${state.connected?'蓝牙已连接':'蓝牙未连接'}</span><i class="divider"></i><span>${icon(state.locked?'lock':'unlock')}${state.connected?(state.locked?'已锁车':'已解锁'):'连接车辆'}</span></button>`}
function car(){if(!state.paired)return header('我的车辆','特斯拉蓝牙钥匙')+`<div class="badges"><span class="badge blue">原型预览</span></div><div class="empty">${icon('car-front')}<h3>添加你的第一把钥匙</h3><p>将手机与车辆配对，<br>开启近距离蓝牙控制。</p><button class="wide blue" onclick="navigate('add')">添加蓝牙钥匙</button></div>`;let off=!state.connected?'disabled':'';return header('我的 Model Y','特斯拉蓝牙钥匙')+`<div class="badges"><span class="badge blue">原型预览</span><span class="badge">演示车辆</span></div><div class="hero ${state.skin==='classic'?'compact':''}"><img class="car" src="assets/car-top.png" alt="银色 Model Y 俯视图">${state.skin==='cockpit'?`<button class="hotspot front" ${off} onclick="sendVehicleCommand('frunk')" aria-label="打开前备箱">前备箱<span>${state.frunk?'已打开':'打开'}</span></button><button class="hotspot rear" ${off} onclick="sendVehicleCommand('trunk')" aria-label="${state.trunk?'关闭后备箱':'打开后备箱'}">后备箱<span>${state.trunk?'关闭':'打开'}</span></button>`:''}</div>`+status()+(state.skin==='classic'?`<div class="grid"><button ${off} onclick="sendVehicleCommand('frunk')">${icon('box-arrow-up')}打开前备箱</button><button ${off} onclick="sendVehicleCommand('trunk')">${icon('box-arrow-up')}${state.trunk?'关闭':'打开'}后备箱</button><button ${off} onclick="sendVehicleCommand('unlock')">${icon('unlock')}解锁</button><button ${off} onclick="sendVehicleCommand('lock')">${icon('lock')}锁车</button></div>`:`<div class="actions"><button class="primary" ${off} onclick="sendVehicleCommand('unlock')">${icon('unlock')}解锁</button><button ${off} onclick="sendVehicleCommand('lock')">${icon('lock')}锁车</button></div><p class="hint">${state.connected?'点击车身标记进行操作':'连接车辆后可使用控制功能'}</p>`)}
function row(i,title,sub,action,trailing=''){return `<button class="row" onclick="${action}">${icon(i)}<div><b>${title}</b>${sub?`<small>${sub}</small>`:''}</div><span class="trailing">${trailing}${icon('chevron-right')}</span></button>`}
function me(){return header('我的','每一次出发，都从这里开始')+`<div class="content"><div class="section-label">蓝牙钥匙</div><div class="panel"><h3>${state.paired?'我的 Model Y':'还没有车辆钥匙'}</h3><p>${state.paired?'此手机 · '+(state.connected?'已连接':'未连接'):'在车旁完成配对，即可使用蓝牙控制。'}</p><button class="wide ${state.paired?'secondary':'blue'}" onclick="navigate('${state.paired?'keys':'add'}')">${state.paired?'管理蓝牙钥匙':'添加蓝牙钥匙'}</button></div>${row('plus-lg','添加蓝牙钥匙','搜索并配对你的车辆',"navigate('add')")}<div class="section-label">个性化</div>${row('palette','外观与模式','选择适合你的控制方式',"navigate('skin')",state.skin==='cockpit'?'车机版':'功能版')}${row('gear','设置','操作确认与应用信息',"navigate('settings')")}<p class="footer-note">特斯拉蓝牙钥匙 · 安卓版<br>产品原型 0.1 · 模拟操作</p></div>`}
function skin(){return header('外观与模式','',true)+`<div class="content"><p class="muted">同一把钥匙，两种控制方式。</p><button class="mode ${state.skin==='cockpit'?'selected':''}" onclick="setSkin('cockpit')">${icon('car-front')}<div>车机版<small>车辆俯视图 · 点击部位控制</small></div><span class="choice"></span></button><button class="mode ${state.skin==='classic'?'selected':''}" onclick="setSkin('classic')">${icon('broadcast')}<div>功能版<small>经典大按钮 · 常用操作一目了然</small></div><span class="choice"></span></button><p class="smallnote">两种模式均采用深色外观，可随时切换。</p><button class="wide" onclick="navigate('car')" style="margin-top:24px">查看车辆页面</button></div>`}
function setSkin(s){state.skin=s;localStorage.setItem('ble-skin',s);render()}
function settings(){return header('设置','',true)+`<div class="content"><div class="section-label">操作偏好</div><div class="row">${icon('shield-check')}<div><b>打开前备箱前确认</b><small>减少误触造成的意外开启</small></div><button class="switch ${state.confirm?'on':''}" role="switch" aria-checked="${state.confirm}" aria-label="打开前备箱前确认" onclick="state.confirm=!state.confirm;render()"></button></div>${row('palette','外观与模式','',"navigate('skin')",state.skin==='cockpit'?'车机版':'功能版')}<div class="section-label">关于</div><div class="row"><div><b>特斯拉蓝牙钥匙 · 安卓版</b><small>产品原型 0.1</small></div></div><p class="smallnote">此版本用于界面与流程评审。页面中的连接、配对和车辆状态均为模拟，不会连接或控制真实车辆。</p></div>`}
function keys(){return header('蓝牙钥匙','',true)+`<div class="content">${state.paired?`<div class="panel"><h3>我的 Model Y</h3><p>此手机的蓝牙钥匙</p><div><i class="dot ${state.connected?'':'off'}"></i>${state.connected?'已连接':'未连接'}</div></div>${row('bluetooth',state.connected?'断开连接':'连接车辆','',"connection()")}${row('key','重新配对','搜索车辆并重新添加手机钥匙',"navigate('add')")}<button class="row danger" onclick="removeKey()">移除此手机的钥匙</button><p class="smallnote">移除手机记录不会自动删除车辆端的钥匙。真实使用时，还需在车机「车锁」中删除对应钥匙。</p>`:`<div class="empty">${icon('key')}<h3>暂无蓝牙钥匙</h3><button class="wide blue" onclick="navigate('add')">添加蓝牙钥匙</button></div>`}</div>`}
function add(){let step=state.pairStep;return header('添加蓝牙钥匙','',true)+`<div class="content"><div class="steps"><span class="done"></span><span class="${step>0?'done':''}"></span><span class="${step>1?'done':''}"></span></div>`+(step===0?`<h2>先找到你的车辆</h2><p class="muted">请靠近车辆，并准备一张已授权的实体钥匙卡。</p><label class="field-label" for="vin">车辆 VIN</label><input id="vin" maxlength="17" placeholder="输入 17 位车辆识别码" autocomplete="off" value="${state.vin||''}"><p class="smallnote" id="vin-error">VIN 可在车机「软件」页面或前挡风玻璃处查看。</p><button class="wide blue" onclick="startScan(false)" style="margin-top:20px">搜索车辆</button><button class="wide secondary" onclick="startScan(true)">使用演示车辆体验</button><p class="smallnote">原型不会请求蓝牙权限。正式版需开启手机蓝牙并允许附近设备访问。</p>`:step===1?`<h2>${state.scan==='scanning'?'正在搜索附近车辆':'找到演示车辆'}</h2><div class="scan-orbit ${state.scan==='scanning'?'scanning':''}">${icon('bluetooth')}</div>${state.scan==='scanning'?`<p class="hint">请保持手机靠近车辆</p><button class="wide secondary" onclick="cancelScan()">取消搜索</button>`:`<button class="row panel" onclick="selectCar()">${icon('car-front')}<div><b>Model Y · 演示车辆</b><small>仅用于体验配对流程</small></div><span class="trailing">配对${icon('chevron-right')}</span></button><button class="wide secondary" onclick="startScan(true)" style="margin-top:25px">重新搜索</button>`}`:step===2?`<h2>确认添加这把钥匙</h2><p class="muted">Model Y · 演示车辆</p><div class="scan-orbit">${icon('key')}</div><div class="instruction"><em>1</em><p>坐进车辆，将已授权的实体钥匙卡放到车辆指定感应区。</p></div><div class="instruction"><em>2</em><p>按照车机提示确认添加此手机钥匙。</p></div><p class="smallnote">感应位置及确认方式以车型和车机提示为准。</p><button class="wide blue" onclick="finishPair()">模拟车端确认完成</button><button class="wide secondary" onclick="pairFail()">体验配对失败</button>`:`<div class="success-icon">${icon('check2')}</div><h2 style="text-align:center">蓝牙钥匙已添加</h2><p class="muted" style="text-align:center">我的 Model Y · 此手机<br>演示配对完成，可以体验车辆控制。</p><button class="wide blue" style="margin-top:35px" onclick="navigate('car')">进入车辆</button>`)+`</div>`}
function startScan(demoMode){let input=$('#vin');if(!demoMode&&input){let v=input.value.trim().toUpperCase();if(!/^[A-HJ-NPR-Z0-9]{17}$/.test(v)){let e=$('#vin-error');e.textContent='请输入有效的 17 位 VIN（不含 I、O、Q）。';e.style.color='#ff969a';return}state.vin=v}clearTimeout(timer);state.pairStep=1;state.scan='scanning';render();timer=setTimeout(()=>{if(state.page==='add'&&state.pairStep===1){state.scan='found';render()}},1400)}
function cancelScan(){clearTimeout(timer);state.pairStep=0;state.scan='idle';render()}
function selectCar(){state.pairStep=2;render()}
function finishPair(){state.paired=true;state.connected=true;state.pairStep=3;render()}
function pairFail(){sheet('未能完成配对','未收到车辆确认。请检查实体卡感应位置，并重新按车机提示操作。','重新尝试',()=>{$('#overlay').innerHTML='';state.pairStep=2;render()})}
function sheet(title,body,label,fn){modalReturn=document.activeElement;$('#overlay').innerHTML=`<div class="sheet-cover"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><button class="close" aria-label="关闭" onclick="closeSheet()">${icon('x-lg')}</button><h3 id="dialog-title">${title}</h3><p>${body}</p><button class="wide" id="sheet-confirm">${label}</button><button class="wide secondary" onclick="closeSheet()">取消</button></section></div>`;$('#sheet-confirm').onclick=fn;$('#sheet-confirm').focus()}
function closeSheet(){$('#overlay').innerHTML='';modalReturn?.focus()}
function sendVehicleCommand(kind){if(!state.connected)return;if(kind==='frunk'&&state.confirm){sheet('打开前备箱？','请确认前备箱上方没有障碍物。前备箱打开后需手动关闭。','确认打开',()=>{closeSheet();execute(kind)});return}execute(kind)}
function execute(k){if(k==='lock')state.locked=true;if(k==='unlock')state.locked=false;if(k==='frunk')state.frunk=true;if(k==='trunk')state.trunk=!state.trunk;render();toast(({lock:'车辆已锁定',unlock:'车辆已解锁',frunk:'前备箱已打开，关闭时请手动操作',trunk:state.trunk?'后备箱已打开':'后备箱已关闭'})[k]+'（模拟）')}
function connection(){if(!state.paired){navigate('add');return}if(state.connected){sheet('断开蓝牙连接？','断开后，连接车辆即可继续使用控制功能。','断开连接',()=>{state.connected=false;closeSheet();render()})}else{sheet('连接我的 Model Y','请靠近车辆并开启手机蓝牙。','模拟连接',()=>{state.connected=true;closeSheet();render()})}}
function removeKey(){sheet('移除此手机的钥匙？','此操作清除原型中的配对记录。车辆端钥匙需在车机上另行删除。','移除记录',()=>{state.paired=false;state.connected=false;closeSheet();render()})}
function demo(mode){clearTimeout(timer);state.paired=mode!=='empty';state.connected=mode==='connected';state.page='car';state.pairStep=0;state.locked=true;state.frunk=false;state.trunk=false;$('#overlay').innerHTML='';render()}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeSheet();if(e.key==='Tab'&&$('#overlay').children.length){const els=[...$('#overlay').querySelectorAll('button')];const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
const navOriginal=navigate;navigate=function(page){if(page==='add'&&state.page!=='add'){state.pairStep=0;state.scan='idle'}navOriginal(page)};render();
